0_2"}]}, "Period": 60, "Stat": "Sum"}, "ReturnData": false}, {"Id": "rt", "MetricStat": {"Metric": {"Namespace": "AWS/EBS", "MetricName": "VolumeTotalReadTime", "Dimensions": [{"Name": "VolumeId", "Value": "vol-0123456789abcdef0_2"}]}, "Period": 60, "Stat": "Sum"}, "ReturnData": false}, {"Id": "wt", "MetricStat": {"Metric": {"Namespace": "AWS/EBS", "MetricName": "VolumeTotalWriteTime", "Dimensions": [{"Name": "VolumeId", "Value": "vol-0123456789abcdef0_2"}]}, "Period": 60, "Stat": "Sum"}, "ReturnData": false}, {"Id": "iops", "Expression": "(rops+wops)/60", "Label": "IOPS"}, {"Id": "mibs", "Expression": "(rb+wb)/60/1048576", "Label": "MiBps"}, {"Id": "rlat", "Expression": "IF(rops>0, rt/rops*1000, 0)", "Label": "ReadLatMs"}, {"Id": "wlat", "Expression": "IF(wops>0, wt/wops*1000, 0)", "Label": "WriteLatMs"}, {"Id": "ql", "MetricStat": {"Metric": {"Namespace": "AWS/EBS", "MetricName": "VolumeQueueLength", "Dimensions": [{"Name": "VolumeId", "Value": "vol-0123456789abcdef0_2"}]}, "Period": 60, "Stat": "Average"}}, {"Id": "idle", "MetricStat": {"Metric": {"Namespace": "AWS/EBS", "MetricName": "VolumeIdleTime", "Dimensions": [{"Name": "VolumeId", "Value": "vol-0123456789abcdef0_2"}]}, "Period": 60, "Stat": "Sum"}}]}, "service_name": "cloudwatch"}, "type": "tool_use"}], "user_reference": null}
